import { cn } from "@/lib/cn";

// Two links in a labelled navigation group, not tabs and not a toggle.
// The current one has aria-current="page"; activating it does nothing. The consumer must keep focus on the activated link on re-render.

export type WeekSwitcherProps = {
  current: "this" | "next";
  thisWeekHref: string;
  nextWeekHref: string;
  /** Called when the other week's link is activated (call preventDefault for client-side routing). */
  onSelect?: (week: "this" | "next", event: React.MouseEvent<HTMLAnchorElement>) => void;
  /** Group name (provisional).*/
  label?: string;
  labels?: { this: string; next: string };
};

const segment =
  "flex min-h-control items-center justify-center rounded-segment border-bw-default border-transparent px-inset-md text-center font-body text-ui-reading leading-normal [overflow-wrap:anywhere] " +
  "transition-colors duration-fast ease-standard focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring";

export function WeekSwitcher({ current, thisWeekHref, nextWeekHref, onSelect, label = "Week", labels = { this: "This week", next: "Next week" } }: WeekSwitcherProps) {
  const items = [
    { key: "this", href: thisWeekHref, text: labels.this },
    { key: "next", href: nextWeekHref, text: labels.next },
  ] as const;
  return (
    <nav aria-label={label}>
      <ul role="list" className="flex rounded-control border-bw-default border-border bg-surface-raised p-1">
        {items.map((it) => {
          const selected = it.key === current;
          return (
            <li key={it.key} className="flex-1">
              <a
                href={it.href}
                aria-current={selected ? "page" : undefined}
                onClick={(e) => {
                  if (selected) e.preventDefault();
                  else onSelect?.(it.key, e);
                }}
                className={cn(
                  segment,
                  selected
                    ? "bg-primary font-medium text-primary-on no-underline hover:bg-primary-hover active:bg-primary-active"
                    : "font-regular text-primary-text hover:underline active:text-text active:underline",
                )}
              >
                {it.text}
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
